"""
    Implements the minimum set cover algorithm to find non-overlapping sets
    out of the 80 ribosomal sampled regions

    Parameters
    ----------
    nodelist: list
    listofsubsets: list

    Returns
    -------
    cover: list
        list of sets of sampled regions
    """
def get_minimum_set_cover(nodelist: Any, listofsubsets: Any) -> object {
    indices = `set(range(len(nodelist)));
    elems = `set(e for s in listofsubsets for e in s);
    if (elems != indices) {
        return None;
    }
    covered = `set();
    cover = [];
    while (covered != elems) {
        subset = max(listofsubsets, key=lambda (s: Any) { len((s - covered)); });
        cover.append(subset);
        covered |= subset;
    }
    return cover;
}

