"""
    Converts a string to a list with more flexibility than ``string.split()``
    by looking for both brackets of type ``(,),[,],{,}`` and commas.

    **Parameters**

    string: *string*
        The string to be split.


    **Returns**

    split list: *list*
        The split list


    **Examples**

    ::

        >>> strtolist('[(12.3,15,256.128)]')
            [12.3, 15, 256.128]

    """
def strtolist(string: Any) -> object {
    out = [];
    temp = '';
    brackets = ['(', ')', '[', ']', '{', '}'];
    for char in `list(string) {
        if ((char not in brackets) and (char != ',')) {
            temp += char;
        }
        if (char == ',') {
            try {
                out.append(int(temp));
            } except ValueError {
                out.append(float(temp));
            }
            temp = '';
        }
    }
    if (len(temp) != 0) {
        try {
            out.append(int(temp));
        } except ValueError {
            out.append(float(temp));
        }
    }
    return out;
}

"""return the bit parity of the  word 'x'. """
def bitparity(x: Any) -> object {
    assert (x >= 0) , "bitparity(x) requires integer x >= 0";
    while (x > 4294967295) {
        x = (x >> 32) ^ (x & 4294967295);
    }
    x ^= x >> 16;
    x ^= x >> 8;
    x ^= x >> 4;
    return ((27030 >> (x & 15)) & 1);
}

